-- Module 16 HR & Payroll expansion
CREATE TYPE "HrRecruitmentStatus" AS ENUM ('OPEN','SCREENING','SHORTLISTED','INTERVIEW','SELECTED','REJECTED','ON_HOLD','CLOSED');
CREATE TYPE "HrApplicationStatus" AS ENUM ('APPLIED','SCREENING','SHORTLISTED','INTERVIEW','SELECTED','REJECTED','JOINED');
CREATE TYPE "HrShiftStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "HrOvertimeStatus" AS ENUM ('PENDING','APPROVED','REJECTED','PAID');
CREATE TYPE "HrBiometricType" AS ENUM ('CHECK_IN','CHECK_OUT','BREAK_IN','BREAK_OUT');
CREATE TYPE "HrAppraisalStatus" AS ENUM ('DRAFT','SUBMITTED','REVIEWED','APPROVED');
CREATE TYPE "HrCertificationType" AS ENUM ('WELDER','OPERATOR','OTHER');
CREATE TYPE "HrCertificationStatus" AS ENUM ('ACTIVE','EXPIRED','SUSPENDED');
CREATE TYPE "HrTrainingStatus" AS ENUM ('PLANNED','IN_PROGRESS','COMPLETED','CANCELLED');
CREATE TABLE "HrRecruitment" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"requisitionNumber" text NOT NULL UNIQUE,"jobTitle" text NOT NULL,"departmentId" text,"positions" integer NOT NULL DEFAULT 1,"description" text,"status" "HrRecruitmentStatus" NOT NULL DEFAULT 'OPEN',"openingDate" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"closingDate" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HrRecruitment_status_idx" ON "HrRecruitment"("status");
CREATE INDEX "HrRecruitment_departmentId_idx" ON "HrRecruitment"("departmentId");
CREATE TABLE "HrRecruitmentApplication" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"recruitmentId" text NOT NULL,"candidateName" text NOT NULL,"email" text,"phone" text,"experienceYears" numeric(5,2) NOT NULL DEFAULT 0,"resumeUrl" text,"status" "HrApplicationStatus" NOT NULL DEFAULT 'APPLIED',"interviewDate" timestamptz,"notes" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HrRecruitmentApplication_recruitmentId_fkey" FOREIGN KEY("recruitmentId") REFERENCES "HrRecruitment"("id") ON DELETE CASCADE);
CREATE INDEX "HrRecruitmentApplication_recruitmentId_idx" ON "HrRecruitmentApplication"("recruitmentId"); CREATE INDEX "HrRecruitmentApplication_status_idx" ON "HrRecruitmentApplication"("status");
CREATE TABLE "HrShift" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"code" text NOT NULL UNIQUE,"name" text NOT NULL,"startTime" text NOT NULL,"endTime" text NOT NULL,"graceMinutes" integer NOT NULL DEFAULT 0,"status" "HrShiftStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HrShiftAssignment" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" text NOT NULL,"shiftId" text NOT NULL,"effectiveFrom" timestamptz NOT NULL,"effectiveTo" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HrShiftAssignment_shiftId_fkey" FOREIGN KEY("shiftId") REFERENCES "HrShift"("id") ON DELETE CASCADE);
CREATE INDEX "HrShiftAssignment_employeeId_idx" ON "HrShiftAssignment"("employeeId"); CREATE INDEX "HrShiftAssignment_shiftId_idx" ON "HrShiftAssignment"("shiftId");
CREATE TABLE "HrOvertime" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" text NOT NULL,"date" timestamptz NOT NULL,"hours" numeric(6,2) NOT NULL,"rate" numeric(12,2) NOT NULL DEFAULT 0,"amount" numeric(15,2) NOT NULL DEFAULT 0,"reason" text,"status" "HrOvertimeStatus" NOT NULL DEFAULT 'PENDING',"approvedBy" text,"approvedAt" timestamptz,"paidAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HrOvertime_employeeId_date_idx" ON "HrOvertime"("employeeId","date"); CREATE INDEX "HrOvertime_status_idx" ON "HrOvertime"("status");
CREATE TABLE "HrBiometricLog" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" text NOT NULL,"biometricId" text,"eventType" "HrBiometricType" NOT NULL,"eventAt" timestamptz NOT NULL,"deviceId" text,"source" text NOT NULL DEFAULT 'BIOMETRIC',"rawPayload" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HrBiometricLog_employeeId_eventAt_idx" ON "HrBiometricLog"("employeeId","eventAt"); CREATE INDEX "HrBiometricLog_biometricId_eventAt_idx" ON "HrBiometricLog"("biometricId","eventAt");
CREATE TABLE "HrAppraisal" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" text NOT NULL,"appraisalPeriod" text NOT NULL,"reviewDate" timestamptz,"rating" numeric(4,2) NOT NULL DEFAULT 0,"goalsScore" numeric(4,2) NOT NULL DEFAULT 0,"skillScore" numeric(4,2) NOT NULL DEFAULT 0,"attendanceScore" numeric(4,2) NOT NULL DEFAULT 0,"comments" text,"status" "HrAppraisalStatus" NOT NULL DEFAULT 'DRAFT',"reviewerId" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HrAppraisal_employeeId_appraisalPeriod_idx" ON "HrAppraisal"("employeeId","appraisalPeriod"); CREATE INDEX "HrAppraisal_status_idx" ON "HrAppraisal"("status");
CREATE TABLE "HrSkill" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"skillCode" text NOT NULL UNIQUE,"name" text NOT NULL,"category" text,"description" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HrEmployeeSkill" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" text NOT NULL,"skillId" text NOT NULL,"level" integer NOT NULL DEFAULT 1,"assessedOn" timestamptz,"assessor" text,"notes" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HrEmployeeSkill_skillId_fkey" FOREIGN KEY("skillId") REFERENCES "HrSkill"("id") ON DELETE CASCADE,CONSTRAINT "HrEmployeeSkill_employee_skill_unique" UNIQUE("employeeId","skillId"));
CREATE INDEX "HrEmployeeSkill_employeeId_idx" ON "HrEmployeeSkill"("employeeId");
CREATE TABLE "HrCertification" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" text NOT NULL,"certificationType" "HrCertificationType" NOT NULL,"certificationName" text NOT NULL,"certificateNumber" text,"issuingAuthority" text,"issueDate" timestamptz,"expiryDate" timestamptz,"status" "HrCertificationStatus" NOT NULL DEFAULT 'ACTIVE',"documentUrl" text,"notes" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HrCertification_employeeId_idx" ON "HrCertification"("employeeId"); CREATE INDEX "HrCertification_expiryDate_idx" ON "HrCertification"("expiryDate"); CREATE INDEX "HrCertification_type_status_idx" ON "HrCertification"("certificationType","status");
CREATE TABLE "HrTraining" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"trainingCode" text NOT NULL UNIQUE,"title" text NOT NULL,"trainer" text,"provider" text,"startDate" timestamptz NOT NULL,"endDate" timestamptz,"status" "HrTrainingStatus" NOT NULL DEFAULT 'PLANNED',"certificateIssued" boolean NOT NULL DEFAULT false,"notes" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HrTrainingParticipant" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"trainingId" text NOT NULL,"employeeId" text NOT NULL,"attendanceStatus" text NOT NULL DEFAULT 'PENDING',"score" numeric(5,2) NOT NULL DEFAULT 0,"certificateUrl" text,"completedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HrTrainingParticipant_trainingId_fkey" FOREIGN KEY("trainingId") REFERENCES "HrTraining"("id") ON DELETE CASCADE,CONSTRAINT "HrTrainingParticipant_unique" UNIQUE("trainingId","employeeId"));
CREATE INDEX "HrTrainingParticipant_employeeId_idx" ON "HrTrainingParticipant"("employeeId");
CREATE TABLE "HrPayslip" ("id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,"payslipNumber" text NOT NULL UNIQUE,"payrollItemId" text NOT NULL UNIQUE,"employeeId" text NOT NULL,"month" integer NOT NULL,"year" integer NOT NULL,"grossSalary" numeric(15,2) NOT NULL DEFAULT 0,"deductions" numeric(15,2) NOT NULL DEFAULT 0,"netSalary" numeric(15,2) NOT NULL DEFAULT 0,"issuedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"pdfUrl" text,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HrPayslip_employeeId_year_month_idx" ON "HrPayslip"("employeeId","year","month");
